#!/usr/bin/env python3
"""Read ids.txt and print the next order id (ORD-XXXX in base-36)."""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def next_id(last: str) -> str:
    """Increment a 4-character base-36 id string, returning the next value."""
    chars = list(last)
    for i in range(3, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            break
        chars[i] = "0"  # carry
    else:
        # All positions wrapped; prefix a new digit (shouldn't happen in practice)
        chars.insert(0, "1")
    return "".join(chars)


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last = lines[-1]
    if not last.startswith("ORD-"):
        print(f"error: unexpected format: {last!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last[4:]
    print(f"ORD-{next_id(suffix)}")


if __name__ == "__main__":
    main()

