#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import string


def encode_base36(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base36 string."""
    chars = string.digits + string.ascii_uppercase
    buf = []
    for _ in range(width):
        buf.append(chars[n % 36])
        n //= 36
    return ''.join(reversed(buf))


def next_id(path: str = 'ids.txt') -> str:
    with open(path) as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        return 'ORD-0000'

    last = lines[-1]
    suffix = last.split('-', 1)[1]
    value = int(suffix, 36) + 1
    return f'ORD-{encode_base36(value, 4)}'


if __name__ == '__main__':
    print(next_id())

