import json
import sys


def main() -> None:
    try:
        with open("orders.json") as f:
            orders = json.load(f)
    except FileNotFoundError:
        print("ERROR: orders.json not found")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"ERROR: orders.json is not valid JSON: {e}")
        sys.exit(1)

    if not isinstance(orders, list):
        print("ERROR: orders.json must contain a JSON array")
        sys.exit(1)

    found_problem = False

    for i, order in enumerate(orders):
        if not isinstance(order, dict):
            print(f"ERROR: entry at index {i} is not an object")
            found_problem = True
            continue

        oid = order.get("id", "")
        if not isinstance(oid, str) or not oid.strip():
            entry_id = order.get("id", f"<index {i}>")
            print(f"ERROR: order {entry_id} has an empty or missing id")
            found_problem = True

        amount = order.get("amount")
        if not isinstance(amount, (int, float)) or amount <= 0:
            entry_id = order.get("id", f"<index {i}>")
            print(f"ERROR: order {entry_id} has amount {amount!r} (must be greater than zero)")
            found_problem = True

    if found_problem:
        sys.exit(1)
    else:
        print("All orders are valid.")


if __name__ == "__main__":
    main()

