"""Validates orders.json before the nightly billing job runs.

Checks:
  - every order has a non-empty id
  - every order has an amount greater than zero
"""

import json
import sys


def main() -> None:
    with open("orders.json", encoding="utf-8") as handle:
        orders = json.load(handle)

    problems: list[str] = []

    for order in orders:
        order_id = order.get("id", "")
        amount = order.get("amount", 0)

        if not order_id:
            problems.append("order with missing or empty id")
        elif amount <= 0:
            problems.append(f"order {order_id} has non-positive amount ({amount})")

    if problems:
        for problem in problems:
            print(problem)
        sys.exit(1)
    else:
        print("all orders valid")


if __name__ == "__main__":
    main()

