#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first), write deduped.jsonl."""

import json

def main():
    seen = set()
    with open("events.jsonl") as inf, open("deduped.jsonl", "w") as outf:
        for line in inf:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event.get("event_id")
            if eid in seen:
                continue
            seen.add(eid)
            outf.write(json.dumps(event, separators=(",", ":")) + "\n")

if __name__ == "__main__":
    main()

