"""Read the version from VERSION and append it to releases.log.

Called by the deploy pipeline after the artefact is uploaded.
The upload occasionally times out and the pipeline is re-run, so
this script is idempotent: if the version is already in releases.log
it does nothing.
"""

from __future__ import annotations

import pathlib

REPO_ROOT = pathlib.Path(__file__).resolve().parent
VERSION_FILE = REPO_ROOT / "VERSION"
RELEASES_FILE = REPO_ROOT / "releases.log"


def current_version() -> str:
    return VERSION_FILE.read_text().strip()


def existing_versions() -> set[str]:
    if not RELEASES_FILE.exists():
        return set()
    return {line.strip() for line in RELEASES_FILE.read_text().splitlines() if line.strip()}


def append_version(version: str) -> None:
    with open(RELEASES_FILE, "a") as f:
        f.write(version + "\n")


def main() -> None:
    version = current_version()
    existing = existing_versions()

    if version in existing:
        print(f"Version {version} already registered — skipping.")
        return

    append_version(version)
    print(f"Registered version {version}.")


if __name__ == "__main__":
    main()

