"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
RELEASE_DIR = REPO_ROOT / "release"
MANIFEST_PATH = REPO_ROOT / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    return hashlib.sha256(filepath.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}

    # Walk all files under release/ sorted for deterministic output
    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        # Relative path from repo root, using forward slashes
        rel_path = str(path.relative_to(REPO_ROOT)).replace("\\", "/")
        manifest[rel_path] = sha256_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote manifest.json with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

