#!/usr/bin/env python3
"""List report files under reports/ in report order (by numeric suffix)."""

import os
import re


def report_sort_key(filename: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"report-(\d+)", filename)
    return int(match.group(1)) if match else 0


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    try:
        files = os.listdir(reports_dir)
    except FileNotFoundError:
        return

    report_files = [f for f in files if re.match(r"report-\d+\.txt", f)]
    report_files.sort(key=report_sort_key)

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

