#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import os
import glob
import collections

PUNCTUATION = set(".,;:!?")

def main():
    counts = collections.Counter()
    cwd = os.getcwd()

    for txt_path in glob.glob(os.path.join(cwd, "docs", "**", "*.txt"), recursive=True):
        with open(txt_path, encoding="utf-8") as f:
            for line in f:
                for raw in line.split():
                    word = raw.lower().strip("".join(PUNCTUATION))
                    if word:
                        counts[word] += 1

    out_path = os.path.join(cwd, "counts.txt")
    with open(out_path, "w", encoding="utf-8") as f:
        for word in sorted(counts):
            f.write(f"{word} {counts[word]}\n")

    print(f"Wrote {len(counts)} unique words to {out_path}")

if __name__ == "__main__":
    main()

