import time


class TransportError(Exception):
    """Raised by a transport when a fetch attempt fails."""


def fetch(url, transport, sleep=time.sleep):
    """Fetch ``url`` via ``transport`` and return its response text.

    Retries up to 8 times when *transport* raises TransportError, sleeping
    between attempts.  If all attempts fail the last TransportError propagates.
    """
    last_exc = None
    for attempt in range(8):
        try:
            return transport(url)
        except TransportError as exc:
            last_exc = exc
            if attempt < 7:
                sleep(1)
    raise last_exc

