"""Rotate app.log entries older than 7 days before AS_OF into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts
with a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message.
Entries strictly older than 7 days before AS_OF are moved to archive.log
(appended, preserving order), and app.log is rewritten with the remaining
entries in their original order.
"""

import sys
from datetime import datetime, timezone


def parse_log_timestamp(s: str) -> datetime | None:
    """Try to parse 'YYYY-MM-DD HH:MM:SS' prefix from a log line."""
    if len(s) < 19:
        return None
    try:
        return datetime.strptime(s[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer, got {sys.argv[1]!r}", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        dt = parse_log_timestamp(line)
        if dt is None:
            # Lines without a valid timestamp prefix are kept in place.
            keep.append(line)
        elif dt < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    with open(log_path, "w") as f:
        f.writelines(keep)

    if archive:
        with open(archive_path, "a") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

